replace_once(
    'packages/testing/src/fake-examinee-repository.ts',
    '  async softDeleteExaminee(\n',
    '''  async importExaminees(\n    records: ExamineeImportRecord[],\n    scope: QuestionBankScope,\n  ): Promise<ExamineeImportWriteResult> {\n    const errors: ExamineeImportWriteResult["errors"] = [];\n    const seenIdentifiers = new Set<string>();\n    const seenCodes = new Set<string>();\n    for (const record of records) {\n      if (seenIdentifiers.has(record.input.identifier)) {\n        errors.push({\n          sheet: record.sheet,\n          row: record.row,\n          identifier: record.input.identifier,\n          message: `代號「${record.input.identifier}」在匯入檔案中重複出現。`,\n        });\n      }\n      if (seenCodes.has(record.input.code)) {\n        errors.push({\n          sheet: record.sheet,\n          row: record.row,\n          identifier: record.input.identifier,\n          message: "密碼在匯入檔案中重複出現。",\n        });\n      }\n      seenIdentifiers.add(record.input.identifier);\n      seenCodes.add(record.input.code);\n\n      if (record.input.groupId !== null) {\n        const group = this.groups.find(\n          (candidate) =>\n            candidate.id === record.input.groupId &&\n            candidate.tenantId === scope.tenantId &&\n            !candidate.deletedAt,\n        );\n        if (!group) {\n          errors.push({\n            sheet: record.sheet,\n            row: record.row,\n            identifier: record.input.identifier,\n            message: `Examinee groupId "${record.input.groupId}" does not exist.`,\n          });\n        }\n      }\n\n      const current = this.examinees.find(\n        (candidate) =>\n          candidate.tenantId === scope.tenantId &&\n          !candidate.deletedAt &&\n          candidate.identifier === record.input.identifier,\n      );\n      const owner = this.examinees.find(\n        (candidate) =>\n          candidate.tenantId === scope.tenantId &&\n          !candidate.deletedAt &&\n          candidate.code === record.input.code,\n      );\n      if (owner && owner.id !== current?.id) {\n        errors.push({\n          sheet: record.sheet,\n          row: record.row,\n          identifier: record.input.identifier,\n          message: "受測者密碼已存在於此租戶。",\n        });\n      }\n    }\n    if (errors.length > 0) {\n      return { imported: 0, updated: 0, errors };\n    }\n\n    const now = new Date().toISOString();\n    let imported = 0;\n    let updated = 0;\n    for (const record of records) {\n      const existing = this.examinees.find(\n        (candidate) =>\n          candidate.tenantId === scope.tenantId &&\n          !candidate.deletedAt &&\n          candidate.identifier === record.input.identifier,\n      );\n      if (existing) {\n        existing.groupId = record.input.groupId;\n        existing.code = record.input.code;\n        existing.name = record.input.name;\n        existing.note = record.input.note;\n        existing.status = record.input.status;\n        existing.version += 1;\n        existing.updatedAt = now;\n        updated += 1;\n      } else {\n        this.examinees.push({\n          id: `examinee-${this.nextExamineeId++}`,\n          tenantId: scope.tenantId,\n          groupId: record.input.groupId,\n          createdBy: scope.actorUserId,\n          code: record.input.code,\n          identifier: record.input.identifier,\n          name: record.input.name,\n          note: record.input.note,\n          status: record.input.status,\n          version: 1,\n          createdAt: now,\n          updatedAt: now,\n          deletedAt: null,\n        });\n        imported += 1;\n      }\n    }\n    return { imported, updated, errors: [] };\n  }\n\n  async softDeleteExaminee(\n''',
)

write(
    'apps/api/src/examinee-import.ts',
    '''import { extname } from "node:path";\nimport * as XLSX from "@e965/xlsx";\nimport {\n  CreateExamineeSchema,\n  type CreateExamineeInput,\n  type ExamineeGroup,\n  type ExamineeImportIssue,\n} from "@server-foundation/api-contracts";\nimport type { ExamineeImportRecord } from "@server-foundation/domain";\n\nexport const MAX_EXAMINEE_IMPORT_BYTES = 10 * 1024 * 1024;\n\nexport type ExamineeImportParseResult = {\n  rows: ExamineeImportRecord[];\n  errors: ExamineeImportIssue[];\n};\n\nconst text = (value: unknown): string => String(value ?? "").trim();\n\nconst issue = (\n  sheet: string | null,\n  row: number | null,\n  identifier: string | null,\n  message: string,\n): ExamineeImportIssue => ({ sheet, row, identifier, message });\n\nconst groupResolver = (groups: ExamineeGroup[]) => {\n  const map = new Map<string, string>();\n  const parentNames = new Map<string, string>();\n  for (const group of groups) {\n    if (group.parentId === null) {\n      parentNames.set(group.id, group.name);\n      map.set(group.name, group.id);\n    }\n  }\n  for (const group of groups) {\n    if (group.parentId !== null) {\n      map.set(group.name, group.id);\n      const parentName = parentNames.get(group.parentId);\n      if (parentName) map.set(`${parentName}/${group.name}`, group.id);\n    }\n  }\n  return (name: string): string | null => (name ? (map.get(name) ?? null) : null);\n};\n\nconst zodMessage = (error: {\n  issues: Array<{ path: PropertyKey[]; message: string }>;\n}): string =>\n  error.issues\n    .map((entry) => {\n      const path = entry.path.map(String).join(".");\n      return path ? `${path}: ${entry.message}` : entry.message;\n    })\n    .join("; ");\n\nexport const parseExamineeImportWorkbook = (\n  buffer: Buffer,\n  filename: string,\n  groups: ExamineeGroup[],\n): ExamineeImportParseResult => {\n  const errors: ExamineeImportIssue[] = [];\n  const rows: ExamineeImportRecord[] = [];\n  const extension = extname(filename).toLowerCase();\n  if (extension !== ".xlsx" && extension !== ".ods") {\n    return {\n      rows,\n      errors: [issue(null, null, null, "只支援 .xlsx 或 .ods 檔案。")],\n    };\n  }\n  if (buffer.byteLength > MAX_EXAMINEE_IMPORT_BYTES) {\n    return {\n      rows,\n      errors: [issue(null, null, null, "檔案大小不可超過 10MB。")],\n    };\n  }\n\n  let workbook: XLSX.WorkBook;\n  try {\n    workbook = XLSX.read(buffer, { type: "buffer" });\n  } catch (error) {\n    return {\n      rows,\n      errors: [\n        issue(\n          null,\n          null,\n          null,\n          `無法讀取試算表：${error instanceof Error ? error.message : String(error)}`,\n        ),\n      ],\n    };\n  }\n\n  const sheetName = workbook.SheetNames[0];\n  if (!sheetName) {\n    return { rows, errors: [issue(null, null, null, "試算表沒有工作表。") ] };\n  }\n  const sheet = workbook.Sheets[sheetName];\n  if (!sheet) {\n    return { rows, errors: [issue(sheetName, null, null, "無法讀取第一個工作表。") ] };\n  }\n  const matrix = XLSX.utils.sheet_to_json<unknown[]>(sheet, {\n    header: 1,\n    raw: false,\n    defval: "",\n    blankrows: false,\n  }) as unknown[][];\n  if (matrix.length < 2) {\n    return {\n      rows,\n      errors: [issue(sheetName, null, null, "檔案內容為空或僅有標題列。")],\n    };\n  }\n\n  const headerRow = (matrix[0] ?? []).map(text);\n  const positions = new Map(headerRow.map((name, index) => [name, index]));\n  for (const required of ["姓名", "代號", "密碼"]) {\n    if (!positions.has(required)) {\n      errors.push(issue(sheetName, 1, null, `缺少必要欄位「${required}」。`));\n    }\n  }\n  if (["姓名", "代號", "密碼"].some((name) => !positions.has(name))) {\n    return { rows, errors };\n  }\n\n  const resolveGroup = groupResolver(groups);\n  const getCell = (values: unknown[], name: string): string => {\n    const index = positions.get(name);\n    return index === undefined ? "" : text(values[index]);\n  };\n\n  for (let index = 1; index < matrix.length; index += 1) {\n    const values = matrix[index] ?? [];\n    if (values.every((value) => text(value) === "")) continue;\n    const row = index + 1;\n    const name = getCell(values, "姓名");\n    const identifier = getCell(values, "代號");\n    const code = getCell(values, "密碼");\n    if (!name) {\n      errors.push(issue(sheetName, row, identifier || null, "姓名為必填。"));\n      continue;\n    }\n    if (!identifier) {\n      errors.push(issue(sheetName, row, null, "代號為必填。"));\n      continue;\n    }\n    if (!code) {\n      errors.push(issue(sheetName, row, identifier, "密碼為必填。"));\n      continue;\n    }\n    if (name.length > 100) {\n      errors.push(issue(sheetName, row, identifier, "姓名不可超過 100 字。"));\n      continue;\n    }\n    if (identifier.length > 100) {\n      errors.push(issue(sheetName, row, identifier, "代號不可超過 100 字。"));\n      continue;\n    }\n    if (code.length > 50) {\n      errors.push(issue(sheetName, row, identifier, "密碼不可超過 50 字。"));\n      continue;\n    }\n\n    const groupName = getCell(values, "群組");\n    const groupId = resolveGroup(groupName);\n    if (groupName && groupId === null) {\n      errors.push(\n        issue(\n          sheetName,\n          row,\n          identifier,\n          `找不到群組「${groupName}」，請先建立。`,\n        ),\n      );\n      continue;\n    }\n    const statusText = getCell(values, "狀態");\n    const status =\n      statusText === "停用" || statusText === "0" ? "disabled" : "enabled";\n    const noteText = getCell(values, "備註");\n    const candidate: CreateExamineeInput = {\n      groupId,\n      code,\n      identifier,\n      name,\n      note: noteText || null,\n      status,\n    };\n    const validated = CreateExamineeSchema.safeParse(candidate);\n    if (!validated.success) {\n      errors.push(issue(sheetName, row, identifier, zodMessage(validated.error)));\n      continue;\n    }\n    rows.push({ sheet: sheetName, row, input: validated.data });\n  }\n\n  if (rows.length === 0 && errors.length === 0) {\n    errors.push(issue(sheetName, null, null, "沒有可匯入的資料。"));\n    return { rows, errors };\n  }\n\n  const identifierRows = new Map<string, ExamineeImportRecord[]>();\n  const codeRows = new Map<string, ExamineeImportRecord[]>();\n  for (const record of rows) {\n    const identifiers = identifierRows.get(record.input.identifier) ?? [];\n    identifiers.push(record);\n    identifierRows.set(record.input.identifier, identifiers);\n    const codes = codeRows.get(record.input.code) ?? [];\n    codes.push(record);\n    codeRows.set(record.input.code, codes);\n  }\n  for (const [identifier, duplicates] of identifierRows) {\n    if (duplicates.length < 2) continue;\n    for (const record of duplicates) {\n      errors.push(\n        issue(\n          record.sheet,\n          record.row,\n          record.input.identifier,\n          `代號「${identifier}」在匯入檔案中重複出現。`,\n        ),\n      );\n    }\n  }\n  for (const duplicates of codeRows.values()) {\n    if (duplicates.length < 2) continue;\n    for (const record of duplicates) {\n      errors.push(\n        issue(\n          record.sheet,\n          record.row,\n          record.input.identifier,\n          "密碼在匯入檔案中重複出現。",\n        ),\n      );\n    }\n  }\n  return { rows, errors };\n};\n''',
)

write(
    'apps/api/src/examinee-import-handler.ts',
    '''import type { ExamineeImportIssue } from "@server-foundation/api-contracts";\nimport {\n  PayloadTooLargeError,\n  type ExamineeService,\n  type QuestionBankScope,\n} from "@server-foundation/domain";\nimport {\n  MAX_EXAMINEE_IMPORT_BYTES,\n  parseExamineeImportWorkbook,\n} from "./examinee-import.js";\n\nexport type ExamineeImportFailure = {\n  ok: false;\n  imported: 0;\n  updated: 0;\n  errors: ExamineeImportIssue[];\n};\n\nexport type ExamineeImportSuccess = {\n  ok: true;\n  imported: number;\n  updated: number;\n  errors: [];\n};\n\nexport type ExamineeImportResult = ExamineeImportFailure | ExamineeImportSuccess;\n\nconst failure = (message: string): ExamineeImportFailure => ({\n  ok: false,\n  imported: 0,\n  updated: 0,\n  errors: [{ sheet: null, row: null, identifier: null, message }],\n});\n\nconst uploadedFile = async (request: Request): Promise<File | null> => {\n  try {\n    const form = await request.formData();\n    const upload = form.get("file");\n    return upload instanceof File ? upload : null;\n  } catch {\n    return null;\n  }\n};\n\nexport const examineeImportFingerprintPayload = async (\n  request: Request,\n): Promise<Buffer | null> => {\n  const upload = await uploadedFile(request);\n  if (!upload) return null;\n  if (upload.size > MAX_EXAMINEE_IMPORT_BYTES) throw new PayloadTooLargeError();\n  const filename = Buffer.from(upload.name, "utf8");\n  const bytes = Buffer.from(await upload.arrayBuffer());\n  return Buffer.concat([filename, Buffer.from([0]), bytes]);\n};\n\nexport const importExamineeWorkbookFromRequest = async (\n  request: Request,\n  service: ExamineeService,\n  scope: QuestionBankScope,\n): Promise<ExamineeImportResult> => {\n  const upload = await uploadedFile(request);\n  if (!upload) {\n    return failure("請使用 multipart/form-data 並以 file 欄位上傳試算表。");\n  }\n  if (upload.size > MAX_EXAMINEE_IMPORT_BYTES) throw new PayloadTooLargeError();\n\n  const groups = await service.listGroups({}, scope);\n  const parsed = parseExamineeImportWorkbook(\n    Buffer.from(await upload.arrayBuffer()),\n    upload.name,\n    groups,\n  );\n  if (parsed.errors.length > 0) {\n    return { ok: false, imported: 0, updated: 0, errors: parsed.errors };\n  }\n\n  const written = await service.importExaminees(parsed.rows, scope);\n  if (written.errors.length > 0) {\n    return {\n      ok: false,\n      imported: 0,\n      updated: 0,\n      errors: written.errors,\n    };\n  }\n  return {\n    ok: true,\n    imported: written.imported,\n    updated: written.updated,\n    errors: [],\n  };\n};\n''',
)

