write(
    'apps/api/test/examinee-import.test.ts',
    '''import * as XLSX from "@e965/xlsx";\nimport {\n  createInMemoryExamineeRepository,\n  createInMemoryItemRepository,\n  createInMemoryQuestionBankRepository,\n} from "@server-foundation/testing";\nimport { describe, expect, it } from "vitest";\nimport { createApp } from "../src/app.js";\nimport { mountQuestionBankRoutes } from "../src/question-bank-routes.js";\n\nconst localScope = {\n  tenantId: "local-development-tenant",\n  actorUserId: "local-development-user",\n};\nconst otherScope = {\n  tenantId: "other-import-tenant",\n  actorUserId: "other-import-user",\n};\n\nconst headers = ["姓名", "代號", "密碼", "群組", "備註", "狀態"];\n\nconst workbookBytes = (\n  rows: unknown[][],\n  bookType: "xlsx" | "ods" = "xlsx",\n): Buffer => {\n  const workbook = XLSX.utils.book_new();\n  XLSX.utils.book_append_sheet(\n    workbook,\n    XLSX.utils.aoa_to_sheet([headers, ...rows]),\n    "受測者",\n  );\n  const output = XLSX.write(workbook, { type: "buffer", bookType });\n  return Buffer.isBuffer(output) ? output : Buffer.from(output as Uint8Array);\n};\n\nconst upload = (bytes: Buffer, filename: string): FormData => {\n  const form = new FormData();\n  form.set(\n    "file",\n    new File([Uint8Array.from(bytes)], filename, {\n      type: "application/octet-stream",\n    }),\n  );\n  return form;\n};\n\nconst createImportApp = () => {\n  const examinees = createInMemoryExamineeRepository();\n  const app = createApp({\n    itemRepository: createInMemoryItemRepository(),\n    allowUnauthenticatedItems: true,\n  });\n  mountQuestionBankRoutes(app, {\n    repository: createInMemoryQuestionBankRepository(),\n    examineeRepository: examinees,\n    allowUnauthenticated: true,\n  });\n  return { app, examinees };\n};\n\ndescribe("examinee import API", () => {\n  it("imports a valid xlsx batch, resolves parent/child groups, and preserves PHP status semantics", async () => {\n    const { app, examinees } = createImportApp();\n    const parent = await examinees.createGroup(\n      {\n        parentId: null,\n        name: "第一梯",\n        proctorPassword: null,\n        sortOrder: 0,\n      },\n      localScope,\n    );\n    const child = await examinees.createGroup(\n      {\n        parentId: parent.id,\n        name: "A班",\n        proctorPassword: null,\n        sortOrder: 0,\n      },\n      localScope,\n    );\n    const response = await app.request("/api/examinee-import", {\n      method: "POST",\n      body: upload(\n        workbookBytes([\n          ["王小明", "S001", "pw-001", "第一梯/A班", "備註", "啟用"],\n          ["陳小華", "S002", "pw-002", "第一梯", "", "停用"],\n        ]),\n        "examinees.xlsx",\n      ),\n    });\n    expect(response.status).toBe(201);\n    expect(await response.json()).toEqual({\n      imported: 2,\n      updated: 0,\n      errors: [],\n    });\n    await expect(examinees.findExamineeByIdentifier("S001", localScope)).resolves.toMatchObject({\n      groupId: child.id,\n      code: "pw-001",\n      status: "enabled",\n    });\n    await expect(examinees.findExamineeByIdentifier("S002", localScope)).resolves.toMatchObject({\n      groupId: parent.id,\n      status: "disabled",\n    });\n  });\n\n  it("accepts ods and upserts by identifier instead of inserting a duplicate", async () => {\n    const { app, examinees } = createImportApp();\n    const first = await app.request("/api/examinee-import", {\n      method: "POST",\n      body: upload(\n        workbookBytes([["原姓名", "UPSERT-1", "old-code", "", "old", "1"]]),\n        "first.xlsx",\n      ),\n    });\n    expect(first.status).toBe(201);\n\n    const second = await app.request("/api/examinee-import", {\n      method: "POST",\n      body: upload(\n        workbookBytes(\n          [["新姓名", "UPSERT-1", "new-code", "", "new", "0"]],\n          "ods",\n        ),\n        "second.ods",\n      ),\n    });\n    expect(second.status).toBe(201);\n    expect(await second.json()).toEqual({\n      imported: 0,\n      updated: 1,\n      errors: [],\n    });\n    await expect(examinees.findExamineeByIdentifier("UPSERT-1", localScope)).resolves.toMatchObject({\n      name: "新姓名",\n      code: "new-code",\n      note: "new",\n      status: "disabled",\n      version: 2,\n    });\n    const page = await examinees.listExaminees({ limit: 100 }, localScope);\n    expect(page.items.filter((item) => item.identifier === "UPSERT-1")).toHaveLength(1);\n  });\n\n  it("rejects duplicate identifiers and passwords inside the upload with row coordinates", async () => {\n    const { app, examinees } = createImportApp();\n    const response = await app.request("/api/examinee-import", {\n      method: "POST",\n      body: upload(\n        workbookBytes([\n          ["甲", "DUP-ID", "DUP-CODE", "", "", ""],\n          ["乙", "DUP-ID", "OTHER-CODE", "", "", ""],\n          ["丙", "OTHER-ID", "DUP-CODE", "", "", ""],\n        ]),\n        "duplicates.xlsx",\n      ),\n    });\n    expect(response.status).toBe(400);\n    const result = await response.json();\n    expect(result).toMatchObject({ imported: 0, updated: 0 });\n    expect(result.errors).toEqual(\n      expect.arrayContaining([\n        expect.objectContaining({\n          sheet: "受測者",\n          row: 2,\n          identifier: "DUP-ID",\n          message: expect.stringContaining("代號"),\n        }),\n        expect.objectContaining({\n          sheet: "受測者",\n          row: 4,\n          identifier: "OTHER-ID",\n          message: expect.stringContaining("密碼"),\n        }),\n      ]),\n    );\n    const page = await examinees.listExaminees({ limit: 100 }, localScope);\n    expect(page.items).toHaveLength(0);\n  });\n\n  it("rolls back the whole batch when a later row conflicts with an existing active password", async () => {\n    const { app, examinees } = createImportApp();\n    await examinees.createExaminee(\n      {\n        groupId: null,\n        code: "TAKEN-CODE",\n        identifier: "EXISTING",\n        name: "existing",\n        note: null,\n        status: "enabled",\n      },\n      localScope,\n    );\n    const response = await app.request("/api/examinee-import", {\n      method: "POST",\n      body: upload(\n        workbookBytes([\n          ["應回滾", "ROLLBACK-NEW", "free-code", "", "", ""],\n          ["衝突", "CONFLICT-NEW", "TAKEN-CODE", "", "", ""],\n        ]),\n        "rollback.xlsx",\n      ),\n    });\n    expect(response.status).toBe(400);\n    const result = await response.json();\n    expect(result).toMatchObject({ imported: 0, updated: 0 });\n    expect(result.errors).toEqual(\n      expect.arrayContaining([\n        expect.objectContaining({\n          row: 3,\n          identifier: "CONFLICT-NEW",\n          message: "受測者密碼已存在於此租戶。",\n        }),\n      ]),\n    );\n    await expect(\n      examinees.findExamineeByIdentifier("ROLLBACK-NEW", localScope),\n    ).resolves.toBeNull();\n  });\n\n  it("allows the same identifier/password in another tenant and hides foreign group existence", async () => {\n    const { app, examinees } = createImportApp();\n    await examinees.createExaminee(\n      {\n        groupId: null,\n        code: "CROSS-CODE",\n        identifier: "CROSS-ID",\n        name: "foreign",\n        note: null,\n        status: "enabled",\n      },\n      otherScope,\n    );\n    const local = await app.request("/api/examinee-import", {\n      method: "POST",\n      body: upload(\n        workbookBytes([["local", "CROSS-ID", "CROSS-CODE", "", "", ""]]),\n        "cross.xlsx",\n      ),\n    });\n    expect(local.status).toBe(201);\n\n    await examinees.createGroup(\n      {\n        parentId: null,\n        name: "FOREIGN-ONLY-GROUP",\n        proctorPassword: null,\n        sortOrder: 0,\n      },\n      otherScope,\n    );\n    const errorFor = async (groupName: string, identifier: string) => {\n      const response = await app.request("/api/examinee-import", {\n        method: "POST",\n        body: upload(\n          workbookBytes([["x", identifier, `${identifier}-code`, groupName, "", ""]]),\n          "group.xlsx",\n        ),\n      });\n      expect(response.status).toBe(400);\n      const body = await response.json();\n      return body.errors[0] as { message: string };\n    };\n    const foreign = await errorFor("FOREIGN-ONLY-GROUP", "FOREIGN-GROUP-ID");\n    const missing = await errorFor("MISSING-GROUP", "MISSING-GROUP-ID");\n    expect(foreign.message.replace("FOREIGN-ONLY-GROUP", "MISSING-GROUP")).toBe(\n      missing.message,\n    );\n  });\n});\n''',
)

write(
    'packages/adapters/mysql/test/examinee-import-repository.integration.test.ts',
    '''import { afterAll, beforeAll, describe, expect, it } from "vitest";\nimport {\n  AesGcmExamineeCredentialProtector,\n  createMySqlPool,\n  MySqlExamineeRepository,\n  runMigrations,\n} from "../src/index.js";\n\nconst connectionString = process.env.MYSQL_TEST_URL;\nif (!connectionString) {\n  throw new Error("MYSQL_TEST_URL is required for the MySQL integration test.");\n}\n\nconst pool = createMySqlPool(connectionString);\nconst credentials = new AesGcmExamineeCredentialProtector(Buffer.alloc(32, 0x50));\nconst repository = new MySqlExamineeRepository(pool, credentials);\nconst scope = {\n  tenantId: "50000000-0000-4000-8000-000000000001",\n  actorUserId: "50000000-0000-4000-8000-000000000002",\n};\nconst otherScope = {\n  tenantId: "50000000-0000-4000-8000-000000000099",\n  actorUserId: "50000000-0000-4000-8000-000000000098",\n};\n\nconst record = (\n  row: number,\n  identifier: string,\n  code: string,\n  groupId: string | null = null,\n) => ({\n  sheet: "受測者",\n  row,\n  input: {\n    groupId,\n    code,\n    identifier,\n    name: `受測者 ${identifier}`,\n    note: null,\n    status: "enabled" as const,\n  },\n});\n\nconst cleanup = async () => {\n  await pool.execute("DELETE FROM examinees WHERE tenant_id IN (?, ?)", [\n    scope.tenantId,\n    otherScope.tenantId,\n  ]);\n  await pool.execute(\n    "DELETE FROM examinee_groups WHERE tenant_id IN (?, ?) AND parent_id IS NOT NULL",\n    [scope.tenantId, otherScope.tenantId],\n  );\n  await pool.execute(\n    "DELETE FROM examinee_groups WHERE tenant_id IN (?, ?) AND parent_id IS NULL",\n    [scope.tenantId, otherScope.tenantId],\n  );\n};\n\ndescribe("MySqlExamineeRepository spreadsheet import", () => {\n  beforeAll(async () => {\n    await runMigrations(pool);\n    await cleanup();\n  });\n\n  afterAll(async () => {\n    await cleanup();\n    await pool.end();\n  });\n\n  it("imports through authenticated encryption and updates by identifier", async () => {\n    const group = await repository.createGroup(\n      {\n        parentId: null,\n        name: "Import group",\n        proctorPassword: null,\n        sortOrder: 0,\n      },\n      scope,\n    );\n    const first = await repository.importExaminees(\n      [record(2, "IMPORT-1", "IMPORT-SECRET", group.id)],\n      scope,\n    );\n    expect(first).toEqual({ imported: 1, updated: 0, errors: [] });\n    const examinee = await repository.findExamineeByIdentifier("IMPORT-1", scope);\n    expect(examinee).toMatchObject({\n      groupId: group.id,\n      code: "IMPORT-SECRET",\n      version: 1,\n    });\n\n    const [rawRows] = await pool.execute<any[]>(\n      "SELECT code_ciphertext, code_digest FROM examinees WHERE id = ?",\n      [examinee!.id],\n    );\n    expect(rawRows[0]?.code_ciphertext).not.toContain("IMPORT-SECRET");\n    expect(rawRows[0]?.code_digest).not.toBe("IMPORT-SECRET");\n    expect(credentials.unprotect(rawRows[0]?.code_ciphertext as string)).toBe(\n      "IMPORT-SECRET",\n    );\n\n    const updated = await repository.importExaminees(\n      [\n        {\n          ...record(2, "IMPORT-1", "IMPORT-SECRET-NEW", null),\n          input: {\n            ...record(2, "IMPORT-1", "IMPORT-SECRET-NEW", null).input,\n            name: "updated name",\n            status: "disabled",\n          },\n        },\n        record(3, "IMPORT-2", "IMPORT-SECRET-2"),\n      ],\n      scope,\n    );\n    expect(updated).toEqual({ imported: 1, updated: 1, errors: [] });\n    await expect(repository.findExamineeByIdentifier("IMPORT-1", scope)).resolves.toMatchObject({\n      code: "IMPORT-SECRET-NEW",\n      name: "updated name",\n      status: "disabled",\n      version: 2,\n    });\n  });\n\n  it("returns row errors and leaves no partial writes on an existing-password conflict", async () => {\n    await repository.createExaminee(\n      {\n        groupId: null,\n        code: "TAKEN-IMPORT-CODE",\n        identifier: "TAKEN-OWNER",\n        name: "owner",\n        note: null,\n        status: "enabled",\n      },\n      scope,\n    );\n    const result = await repository.importExaminees(\n      [\n        record(2, "ROLLBACK-FIRST", "AVAILABLE-CODE"),\n        record(3, "ROLLBACK-SECOND", "TAKEN-IMPORT-CODE"),\n      ],\n      scope,\n    );\n    expect(result.imported).toBe(0);\n    expect(result.updated).toBe(0);\n    expect(result.errors).toEqual([\n      expect.objectContaining({\n        sheet: "受測者",\n        row: 3,\n        identifier: "ROLLBACK-SECOND",\n        message: "受測者密碼已存在於此租戶。",\n      }),\n    ]);\n    await expect(\n      repository.findExamineeByIdentifier("ROLLBACK-FIRST", scope),\n    ).resolves.toBeNull();\n  });\n\n  it("keeps import uniqueness and group references tenant-scoped", async () => {\n    await repository.createExaminee(\n      {\n        groupId: null,\n        code: "SHARED-IMPORT-CODE",\n        identifier: "SHARED-IMPORT-ID",\n        name: "foreign",\n        note: null,\n        status: "enabled",\n      },\n      otherScope,\n    );\n    const local = await repository.importExaminees(\n      [record(2, "SHARED-IMPORT-ID", "SHARED-IMPORT-CODE")],\n      scope,\n    );\n    expect(local).toEqual({ imported: 1, updated: 0, errors: [] });\n\n    const foreignGroup = await repository.createGroup(\n      {\n        parentId: null,\n        name: "Foreign import group",\n        proctorPassword: null,\n        sortOrder: 0,\n      },\n      otherScope,\n    );\n    const foreign = await repository.importExaminees(\n      [record(3, "FOREIGN-GROUP-IMPORT", "FG-CODE", foreignGroup.id)],\n      scope,\n    );\n    const missingId = "50000000-0000-4000-8000-00000000ffff";\n    const missing = await repository.importExaminees(\n      [record(4, "MISSING-GROUP-IMPORT", "MG-CODE", missingId)],\n      scope,\n    );\n    expect(foreign.imported).toBe(0);\n    expect(missing.imported).toBe(0);\n    expect(foreign.errors[0]?.message).toBe(\n      `Examinee groupId "${foreignGroup.id}" does not exist.`,\n    );\n    expect(missing.errors[0]?.message.replace(missingId, foreignGroup.id)).toBe(\n      foreign.errors[0]?.message,\n    );\n  });\n});\n''',
)

write(
    'doc/examinee-import-php-mapping.md',
    '''# Examinee spreadsheet import — PHP mapping\n\nTruth source read before implementation:\n\n- `exam.tw/src/Services/ExamineeImporter.php`\n- `exam.tw/src/Models/ExamineeGroup.php`\n- `exam.tw/src/Pages/Ajax/ExamineeActions.php`\n\n## Preserved behavior\n\nThe server accepts `.xlsx` and `.ods` up to 10 MB and reads the first worksheet, matching PHP. Required headings are `姓名`, `代號`, and `密碼`; optional headings are `群組`, `備註`, and `狀態`. Blank rows are ignored. `identifier` is the tenant-local upsert key: an active matching identifier is updated, otherwise a new examinee is created.\n\nPHP treats only `停用` and `0` as disabled; every other status cell, including blank or unfamiliar text, becomes enabled. The server intentionally preserves that rule rather than inventing a stricter status vocabulary for spreadsheet imports.\n\nGroup lookup is built only from active groups in the authenticated tenant. As in PHP `buildNameMap()`, imports accept a direct group name and `父群組/子群組`. A group that exists only in another tenant is therefore indistinguishable from a nonexistent group to the importer.\n\n## Security boundary retained from #48\n\nSpreadsheet import does not have a parallel SQL/plaintext write path. The parsed batch is passed to `ExamineeRepository.importExaminees()`. The MySQL implementation performs reference/password preflight and every insert/update in one transaction and uses the same #48 `ExamineeCredentialProtector` for AES-256-GCM ciphertext plus keyed password digest.\n\nThe import repository locks the authenticated tenant's active examinees before conflict checking. An existing password is allowed only when it belongs to the same identifier being updated. This also preserves PHP's conservative behavior: a password currently owned by another row remains a conflict even if that other row also appears in the same upload and would have changed its password later in the batch.\n\nNo production credential key is created or changed by this work. The #48 threat model remains unchanged.\n\n## Deliberate presentation improvement\n\nPHP returns a flat array of human-readable strings. The server keeps the same validation meaning but returns structured errors with `sheet`, `row`, `identifier`, and `message`, so the desktop client can point to the exact failing spreadsheet row.\n\n## Transaction semantics\n\nAll parser errors are collected before repository mutation. Repository-level conflicts and group-reference failures are also collected before any write. If either layer reports an error, `imported` and `updated` are both zero and no partial batch is retained.\n\n## Out of scope\n\nThere is no schema migration for this feature; migration 009 remains the examinee authority. This work does not deploy migration 009, provision production credential keys, or modify `exam-control`, `exam-runtime`, `exam-admin-desktop`, or `exam.tw`.\n''',
)

