if not any(e.get('path') == '/api/v1/examinee-import' for e in manifest['endpoints']):
    insert_at = next(i for i, e in enumerate(manifest['endpoints']) if e.get('path') == '/api/v1/examinees')
    manifest['endpoints'].insert(insert_at, {
        'method': 'POST',
        'path': '/api/v1/examinee-import',
        'authenticated': True,
        'idempotent': True,
    })
manifest['responseSchemas']['ExamineeImport'] = {
    'imported': {'type': 'nonnegative-integer', 'required': True},
    'updated': {'type': 'nonnegative-integer', 'required': True},
    'errors': {'type': 'examinee-import-issue-array', 'required': True},
}
manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n')

